// === Unstop Public Search API ===
// India-centric platform for hackathons, case competitions, internships.
// The public search endpoint powers their listings UI; returns rich JSON.
//
// We hit the hackathons surface here. To add competitions/internships,
// clone this workflow and change `opportunity=` query param + category mapping.

let data;
try {
  data = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://unstop.com/api/public/opportunity/search-result?opportunity=hackathons&per_page=20&oppstatus=open',
    json: true,
    headers: { Accept: 'application/json' },
  });
} catch (e) {
  throw new Error('Unstop API fetch failed: ' + ((e && e.message) || e));
}

// Response shape: { data: { current_page, data: [...] } }
const items = (data && data.data && Array.isArray(data.data.data)) ? data.data.data : [];
if (items.length === 0) {
  throw new Error('Unstop returned 0 hackathons');
}

function extractTags(h) {
  const tags = new Set();
  if (Array.isArray(h.required_skills)) {
    for (const s of h.required_skills) {
      const name = (s && (s.name || s.title)) || (typeof s === 'string' ? s : null);
      if (name) tags.add(String(name).toLowerCase());
    }
  }
  if (Array.isArray(h.filters)) {
    for (const f of h.filters) {
      const name = (f && (f.name || f.title)) || (typeof f === 'string' ? f : null);
      if (name) tags.add(String(name).toLowerCase());
    }
  }
  return Array.from(tags).slice(0, 6);
}

function extractLocation(h) {
  // Unstop nests location info in address_with_country_logo or similar
  if (h.address_with_country_logo) {
    const a = h.address_with_country_logo;
    return [a.city, a.state, a.country].filter(Boolean).join(', ') || 'India';
  }
  if (typeof h.location === 'string') return h.location;
  return 'India';
}

function extractCompensation(h) {
  // Prize info lives in different fields depending on the listing.
  if (h.prize_money) return String(h.prize_money);
  if (Array.isArray(h.prizes) && h.prizes.length) {
    const first = h.prizes[0];
    if (first && first.amount) return String(first.amount);
  }
  // Sometimes embedded in description as ₹X,XX,XXX — let admin fix manually.
  return null;
}

function extractEligibility(h) {
  if (h.regnRequirements) {
    const r = h.regnRequirements;
    const parts = [];
    if (r.team_size_min || r.team_size_max) {
      parts.push(`Team size: ${r.team_size_min || 1}-${r.team_size_max || 'any'}`);
    }
    if (r.eligibility) parts.push(String(r.eligibility));
    return parts.length ? parts.join('. ') : null;
  }
  return null;
}

function stripHtml(s) {
  if (!s) return null;
  return String(s).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

const out = [];
for (const h of items) {
  const orgName = (h.organisation && h.organisation.name) || 'Unstop';
  const cleanDesc = stripHtml(h.description);
  const summary = cleanDesc
    ? (cleanDesc.length > 280 ? cleanDesc.slice(0, 277) + '...' : cleanDesc)
    : `Hackathon by ${orgName}`;

  const opportunity = {
    title: h.title,
    organization: orgName,
    category: 'hackathon',
    description: cleanDesc,
    summary: summary,
    tags: extractTags(h),
    deadline: h.end_date || null,  // already ISO 8601
    eligibility: extractEligibility(h),
    location: extractLocation(h),
    compensation: extractCompensation(h),
    is_remote: false,  // Unstop hackathons are mostly offline at colleges
    apply_url: h.seo_url,
    difficulty: null,
    estimated_value_score: null,
    extraction_confidence: 0.9,
  };

  out.push({ json: { opportunity, source_url: h.seo_url } });
}

return out;
